-- Desired database schema for the control plane (source of truth, decision D19).
-- Edit this file, then run `mise run db:diff <name>` to generate a goose migration.
-- Entities are specified in docs/spec/02-domain-model.md. Columns arrive with the
-- milestone that needs them; M1 covers Project, Issue, Run, StepRun and Event.
-- IDs are UUIDv7 generated by the application.

CREATE TABLE projects (
  id                uuid        PRIMARY KEY,
  name              text        NOT NULL UNIQUE,
  -- Issue key prefix (D22): immutable, branch-safe.
  key_prefix        text        NOT NULL UNIQUE CHECK (key_prefix ~ '^[a-z][a-z0-9]{1,9}$'),
  next_issue_number integer     NOT NULL DEFAULT 1 CHECK (next_issue_number >= 1),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE issues (
  id                  uuid        PRIMARY KEY,
  project_id          uuid        NOT NULL REFERENCES projects (id),
  -- Allocated from projects.next_issue_number; key is <key_prefix>-<number> (D22).
  number              integer     NOT NULL CHECK (number >= 1),
  key                 text        NOT NULL UNIQUE,
  type                text        NOT NULL CHECK (type IN ('epic', 'story', 'task', 'bug')),
  title               text        NOT NULL,
  spec                text        NOT NULL DEFAULT '',
  acceptance_criteria text[]      NOT NULL DEFAULT '{}',
  status              text        NOT NULL DEFAULT 'draft' CHECK (status IN (
                        'draft', 'refining', 'ready', 'running', 'awaiting_human',
                        'queued', 'merged', 'released', 'failed', 'canceled')),
  priority            integer     NOT NULL DEFAULT 0,
  source_ref          text,
  labels              text[]      NOT NULL DEFAULT '{}',
  created_by          text        NOT NULL,
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now(),
  -- An external issue (e.g. a GitHub issue URL) syncs into at most one Issue per project.
  CONSTRAINT issues_project_source_ref_key UNIQUE (project_id, source_ref),
  CONSTRAINT issues_project_number_key UNIQUE (project_id, number)
);

CREATE INDEX issues_project_status_idx ON issues (project_id, status);

CREATE TABLE runs (
  id                   uuid        PRIMARY KEY,
  issue_id             uuid        NOT NULL REFERENCES issues (id),
  workflow_snapshot    jsonb       NOT NULL,
  workflow_version     text        NOT NULL,
  -- Stable per issue (e.g. issue-gc-1) and reused by reruns; the Temporal run ID
  -- identifies one execution, so it is what makes a Run unique.
  temporal_workflow_id text        NOT NULL,
  temporal_run_id      text        UNIQUE,
  status               text        NOT NULL DEFAULT 'pending' CHECK (status IN (
                         'pending', 'running', 'succeeded', 'failed', 'canceled')),
  loop_counts          jsonb       NOT NULL DEFAULT '{}',
  started_at           timestamptz,
  finished_at          timestamptz,
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now()
);

-- At most one active Run per Issue; a retry creates a new Run after the old one ends.
CREATE UNIQUE INDEX runs_one_active_per_issue_idx ON runs (issue_id) WHERE status IN ('pending', 'running');

CREATE TABLE step_runs (
  id          uuid        PRIMARY KEY,
  run_id      uuid        NOT NULL REFERENCES runs (id),
  step_id     text        NOT NULL,
  attempt     integer     NOT NULL CHECK (attempt >= 1),
  kind        text        NOT NULL CHECK (kind IN ('agent', 'gate', 'action', 'parallel')),
  status      text        NOT NULL DEFAULT 'pending' CHECK (status IN (
                'pending', 'running', 'succeeded', 'failed', 'canceled')),
  pod_name    text,
  commit_sha  text,
  started_at  timestamptz,
  finished_at timestamptz,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT step_runs_run_step_attempt_key UNIQUE (run_id, step_id, attempt)
);

-- Append-only. seq gives a strict total order for streaming and replay (FR-OB-2).
CREATE TABLE events (
  id          uuid        PRIMARY KEY,
  seq         bigint      NOT NULL GENERATED ALWAYS AS IDENTITY UNIQUE,
  run_id      uuid        REFERENCES runs (id),
  step_run_id uuid        REFERENCES step_runs (id),
  session_id  uuid,
  ts          timestamptz NOT NULL,
  type        text        NOT NULL,
  payload     jsonb       NOT NULL DEFAULT '{}',
  created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX events_run_seq_idx ON events (run_id, seq);

-- A change request (PR/MR) opened for an issue's branch; neutral across providers (D12).
CREATE TABLE change_requests (
  id           uuid        PRIMARY KEY,
  issue_id     uuid        NOT NULL REFERENCES issues (id),
  run_id       uuid        NOT NULL REFERENCES runs (id),
  repo         text        NOT NULL,
  number       integer     NOT NULL,
  provider_ref text        NOT NULL,
  branch       text        NOT NULL,
  head_sha     text        NOT NULL,
  status       text        NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'merged', 'closed')),
  created_at   timestamptz NOT NULL DEFAULT now(),
  updated_at   timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT change_requests_repo_number_key UNIQUE (repo, number)
);
